{
  "findings": [
    {
      "check_id": "CKV_GCP_117",
      "title": "Basic role used at project level",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The 'roles/editor' role is a basic role and should not be used at project level as it grants excessive permissions."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  role    = \"roles/compute.instanceAdmin.v1\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}",
  "fix_summary": "Replaced the basic 'roles/editor' role with 'roles/compute.instanceAdmin.v1' to follow the principle of least privilege."
}
